arguments.command:
cat > tests/lag_alert_test.sh <<'EOF'
#!/bin/bash
fail=0
last=$(date -u -d "$(tail -1 data/readings/latest.csv | cut -d, -f2)" +%s)
out=$(NOW=$((last + 8*3600)) bash ops/lag-alert.sh)
echo "$out" | grep -q '最大 6 時間' || { echo "lag-alert wording: $out"; fail=1; }
echo "$out" | grep -q '24 時間' && { echo "lag-alert still says 24"; fail=1; }
exit $fail
EOF
bash tests/lag_alert_test.sh; sed -i 's/最大 24 時間を超えたら/最大 ${LAG_LIMIT_HOURS} 時間を超えたら/' ops/lag-alert.sh; bash scripts/verify.sh; echo rc=$?

